import math
import torch
import torch.nn as nn
import torch.nn.init as init
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_BODY = r"""
.visible .entry conv3d_square_depth1(
    .param .u64 x_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 y_ptr,
    .param .u32 N,
    .param .u32 C_in,
    .param .u32 C_out,
    .param .u32 D,
    .param .u32 H,
    .param .u32 W,
    .param .u32 kD,
    .param .u32 kH,
    .param .u32 kW,
    .param .u32 stride_d,
    .param .u32 stride_h,
    .param .u32 stride_w,
    .param .u32 pad_d,
    .param .u32 pad_h,
    .param .u32 pad_w,
    .param .u32 dil_d,
    .param .u32 dil_h,
    .param .u32 dil_w,
    .param .u32 groups,
    .param .u32 has_bias,
    .param .u32 D_out,
    .param .u32 H_out,
    .param .u32 W_out,
    .param .u32 z_base
)
{
    // ===== Register and predicate declarations (must be before first instruction) =====
    // Pointers
    .reg .u64 %r_x, %r_w, %r_b, %r_y;
    // Sizes and params
    .reg .u32 %rN, %rCin, %rCout, %rD, %rH, %rW;
    .reg .u32 %rkD, %rkH, %rkW;
    .reg .u32 %rSd, %rSh, %rSw;
    .reg .u32 %rPd, %rPh, %rPw;
    .reg .u32 %rDd, %rDh, %rDw;
    .reg .u32 %rGroups, %rHasBias;
    .reg .u32 %rDo, %rHo, %rWo;
    // Thread indices and mapping
    .reg .u32 %tx, %ty, %bdx, %bdy, %bszx, %bszy, %ow, %oh, %bidz;
    .reg .u32 %zbase;
    // Index math
    .reg .u32 %co_do, %n, %rem1, %oc, %od, %qtmp, %prod;
    // Group/channel ranges
    .reg .u32 %gout, %gin, %grp, %ci_start, %ci_end, %ci, %ci_rel;
    // Loop indices
    .reg .u32 %kd, %kh, %kw;
    // Input indices (unsigned) for address calc
    .reg .u32 %in_d_u32, %in_h_u32, %in_w_u32;
    // Signed temps and converted indices
    .reg .s32 %in_d_s32, %in_h_s32, %in_w_s32, %od_s32, %oh_s32, %ow_s32, %tmp_s32a, %tmp_s32b;
    // Strides for x (N,C,D,H,W), y (N,C,D,H,W), w (C_out, C_in_group, kD, kH, kW)
    .reg .u64 %sX_w, %sX_h, %sX_d, %sX_c, %sX_n;
    .reg .u64 %sY_w, %sY_h, %sY_d, %sY_c, %sY_n;
    .reg .u64 %sW_kw, %sW_kh, %sW_kd, %sW_ci, %sW_co;
    // Generic 64-bit temporaries
    .reg .u64 %tmp64a, %tmp64b, %tmp64c;
    // y indexing temps
    .reg .u64 %y_index_elems, %y_byte_addr;
    .reg .u64 %t64n, %t64oc, %t64od, %t64oh, %t64ow;
    // bias temps
    .reg .u64 %b_off_bytes, %b_idx_elems;
    // x indexing temps
    .reg .u64 %x_idx_elems, %x_addr_bytes, %t64_ci, %t64_id, %t64_ih, %t64_iw;
    // w indexing temps
    .reg .u64 %w_idx_elems, %w_addr_bytes, %t64cirel, %t64kd, %t64kh, %t64kw;
    // Accumulators and values
    .reg .f32 %acc, %bias_val, %xval, %wval, %prod_f;
    // Predicates
    .reg .pred %p_oob_xy, %p_has_bias, %p_ci_done, %p_kd_done, %p_d_oob1, %p_d_oob2, %p_d_oob, %p_kh_done, %p_h_oob1, %p_h_oob2, %p_h_oob, %p_kw_done, %p_w_oob1, %p_w_oob2, %p_w_oob;
    // ===== Load function parameters =====
    ld.param.u64 %r_x, [x_ptr];
    ld.param.u64 %r_w, [w_ptr];
    ld.param.u64 %r_b, [b_ptr];
    ld.param.u64 %r_y, [y_ptr];
    ld.param.u32 %rN,      [N];
    ld.param.u32 %rCin,    [C_in];
    ld.param.u32 %rCout,   [C_out];
    ld.param.u32 %rD,      [D];
    ld.param.u32 %rH,      [H];
    ld.param.u32 %rW,      [W];
    ld.param.u32 %rkD,     [kD];
    ld.param.u32 %rkH,     [kH];
    ld.param.u32 %rkW,     [kW];
    ld.param.u32 %rSd,     [stride_d];
    ld.param.u32 %rSh,     [stride_h];
    ld.param.u32 %rSw,     [stride_w];
    ld.param.u32 %rPd,     [pad_d];
    ld.param.u32 %rPh,     [pad_h];
    ld.param.u32 %rPw,     [pad_w];
    ld.param.u32 %rDd,     [dil_d];
    ld.param.u32 %rDh,     [dil_h];
    ld.param.u32 %rDw,     [dil_w];
    ld.param.u32 %rGroups, [groups];
    ld.param.u32 %rHasBias,[has_bias];
    ld.param.u32 %rDo,     [D_out];
    ld.param.u32 %rHo,     [H_out];
    ld.param.u32 %rWo,     [W_out];
    ld.param.u32 %zbase,   [z_base];
    // ===== Thread/block indices =====
    mov.u32 %tx, %tid.x;
    mov.u32 %ty, %tid.y;
    mov.u32 %bdx, %ctaid.x;
    mov.u32 %bdy, %ctaid.y;
    mov.u32 %bszx, %ntid.x;
    mov.u32 %bszy, %ntid.y;
    mad.lo.u32 %ow, %bdx, %bszx, %tx; // ow = blockIdx.x * blockDim.x + threadIdx.x
    mad.lo.u32 %oh, %bdy, %bszy, %ty; // oh = blockIdx.y * blockDim.y + threadIdx.y
    mov.u32 %bidz, %ctaid.z;
    add.u32 %bidz, %bidz, %zbase;
    // Early bounds check on ow, oh
    setp.ge.u32 %p_oob_xy, %ow, %rWo;
    @%p_oob_xy bra RET;
    setp.ge.u32 %p_oob_xy, %oh, %rHo;
    @%p_oob_xy bra RET;
    // Compute n, oc, od from bidz
    mul.lo.u32 %co_do, %rCout, %rDo;           // C_out * D_out
    div.u32 %qtmp, %bidz, %co_do;              // n = bidz / (C_out*D_out)
    mul.lo.u32 %prod, %qtmp, %co_do;           // n * (C_out*D_out)
    sub.u32 %rem1, %bidz, %prod;               // remainder
    mov.u32 %n, %qtmp;
    div.u32 %oc, %rem1, %rDo;                  // oc = rem1 / D_out
    mul.lo.u32 %prod, %oc, %rDo;
    sub.u32 %od, %rem1, %prod;                 // od = rem1 - oc*D_out
    // Compute group information
    div.u32 %gout, %rCout, %rGroups;           // out channels per group
    div.u32 %gin,  %rCin,  %rGroups;           // in channels per group
    div.u32 %grp,  %oc,    %gout;              // group id
    mul.lo.u32 %ci_start, %grp, %gin;          // start in-channel
    add.u32 %ci_end, %ci_start, %gin;          // end in-channel
    // Precompute strides for x (N,C,D,H,W)
    mov.u64 %sX_w, 1;
    cvt.u64.u32 %tmp64a, %rW;                 // W
    mov.u64 %sX_h, %tmp64a;                   // H stride = W
    cvt.u64.u32 %tmp64b, %rH;                 // H
    mul.lo.u64 %sX_d, %tmp64a, %tmp64b;       // D stride = H*W
    cvt.u64.u32 %tmp64c, %rD;                 // D
    mul.lo.u64 %sX_c, %sX_d, %tmp64c;         // C stride = D*H*W
    cvt.u64.u32 %tmp64a, %rCin;               // C_in
    mul.lo.u64 %sX_n, %sX_c, %tmp64a;         // N stride = C*D*H*W
    // Precompute strides for y (N,C,D,H,W)
    mov.u64 %sY_w, 1;
    cvt.u64.u32 %tmp64a, %rWo;
    mov.u64 %sY_h, %tmp64a;                   // H_out stride
    cvt.u64.u32 %tmp64b, %rHo;
    mul.lo.u64 %sY_d, %tmp64a, %tmp64b;       // D_out stride
    cvt.u64.u32 %tmp64c, %rDo;
    mul.lo.u64 %sY_c, %sY_d, %tmp64c;         // C_out stride
    cvt.u64.u32 %tmp64a, %rCout;
    mul.lo.u64 %sY_n, %sY_c, %tmp64a;         // N stride
    // Precompute strides for weights (C_out, C_in_group, kD, kH, kW)
    mov.u64 %sW_kw, 1;
    cvt.u64.u32 %tmp64a, %rkW;
    mov.u64 %sW_kh, %tmp64a;                  // kH stride
    cvt.u64.u32 %tmp64b, %rkH;
    mul.lo.u64 %sW_kd, %tmp64a, %tmp64b;      // kD stride
    cvt.u64.u32 %tmp64c, %rkD;
    mul.lo.u64 %sW_ci, %sW_kd, %tmp64c;       // C_in_group stride
    cvt.u64.u32 %tmp64a, %gin;
    mul.lo.u64 %sW_co, %sW_ci, %tmp64a;       // C_out stride
    // Compute y element address
    cvt.u64.u32 %t64n,  %n;
    cvt.u64.u32 %t64oc, %oc;
    cvt.u64.u32 %t64od, %od;
    cvt.u64.u32 %t64oh, %oh;
    cvt.u64.u32 %t64ow, %ow;
    mul.lo.u64 %y_index_elems, %t64n,  %sY_n;
    mad.lo.u64 %y_index_elems, %t64oc, %sY_c, %y_index_elems;
    mad.lo.u64 %y_index_elems, %t64od, %sY_d, %y_index_elems;
    mad.lo.u64 %y_index_elems, %t64oh, %sY_h, %y_index_elems;
    add.u64    %y_index_elems, %y_index_elems, %t64ow;
    mul.lo.u64 %y_byte_addr, %y_index_elems, 4;
    add.u64    %y_byte_addr, %y_byte_addr, %r_y;
    // Accumulator and optional bias
    mov.f32 %acc, 0f00000000; // 0.0
    setp.ne.u32 %p_has_bias, %rHasBias, 0;
    @!%p_has_bias bra NO_BIAS_LOAD;
        // bias[oc]
        cvt.u64.u32 %b_idx_elems, %oc;
        mul.lo.u64 %b_off_bytes, %b_idx_elems, 4;
        add.u64 %b_off_bytes, %b_off_bytes, %r_b;
        ld.global.f32 %bias_val, [%b_off_bytes];
        add.f32 %acc, %acc, %bias_val;
    NO_BIAS_LOAD:
    // Loop over input channels in the group
    mov.u32 %ci, %ci_start;
CI_LOOP:
    setp.ge.u32 %p_ci_done, %ci, %ci_end;
    @%p_ci_done bra WRITE_OUT;
    sub.u32 %ci_rel, %ci, %ci_start;
    // kd loop
    mov.u32 %kd, 0;
KD_LOOP:
    setp.ge.u32 %p_kd_done, %kd, %rkD;
    @%p_kd_done bra NEXT_CI;
    // Compute in_d = od*stride_d - pad_d + kd*dil_d
    cvt.s32.u32 %od_s32, %od;
    cvt.s32.u32 %tmp_s32a, %rSd;
    mul.lo.s32 %in_d_s32, %od_s32, %tmp_s32a;      // od*stride_d
    cvt.s32.u32 %tmp_s32b, %rPd;
    sub.s32 %in_d_s32, %in_d_s32, %tmp_s32b;       // - pad_d
    cvt.s32.u32 %tmp_s32a, %rDd;
    cvt.s32.u32 %tmp_s32b, %kd;
    mul.lo.s32 %tmp_s32b, %tmp_s32a, %tmp_s32b;    // kd*dil_d
    add.s32 %in_d_s32, %in_d_s32, %tmp_s32b;
    // Bounds check D
    setp.lt.s32 %p_d_oob1, %in_d_s32, 0;
    cvt.s32.u32 %tmp_s32a, %rD;
    setp.ge.s32 %p_d_oob2, %in_d_s32, %tmp_s32a;
    or.pred %p_d_oob, %p_d_oob1, %p_d_oob2;
    @%p_d_oob bra INC_KD;
    // kh loop
    mov.u32 %kh, 0;
KH_LOOP:
    setp.ge.u32 %p_kh_done, %kh, %rkH;
    @%p_kh_done bra INC_KD;
    // Compute in_h = oh*stride_h - pad_h + kh*dil_h
    cvt.s32.u32 %oh_s32, %oh;
    cvt.s32.u32 %tmp_s32a, %rSh;
    mul.lo.s32 %in_h_s32, %oh_s32, %tmp_s32a;      // oh*stride_h
    cvt.s32.u32 %tmp_s32b, %rPh;
    sub.s32 %in_h_s32, %in_h_s32, %tmp_s32b;       // - pad_h
    cvt.s32.u32 %tmp_s32a, %rDh;
    cvt.s32.u32 %tmp_s32b, %kh;
    mul.lo.s32 %tmp_s32b, %tmp_s32a, %tmp_s32b;    // kh*dil_h
    add.s32 %in_h_s32, %in_h_s32, %tmp_s32b;
    // Bounds check H
    setp.lt.s32 %p_h_oob1, %in_h_s32, 0;
    cvt.s32.u32 %tmp_s32a, %rH;
    setp.ge.s32 %p_h_oob2, %in_h_s32, %tmp_s32a;
    or.pred %p_h_oob, %p_h_oob1, %p_h_oob2;
    @%p_h_oob bra INC_KH;
    // kw loop
    mov.u32 %kw, 0;
KW_LOOP:
    setp.ge.u32 %p_kw_done, %kw, %rkW;
    @%p_kw_done bra INC_KH;
    // Compute in_w = ow*stride_w - pad_w + kw*dil_w
    cvt.s32.u32 %ow_s32, %ow;
    cvt.s32.u32 %tmp_s32a, %rSw;
    mul.lo.s32 %in_w_s32, %ow_s32, %tmp_s32a;      // ow*stride_w
    cvt.s32.u32 %tmp_s32b, %rPw;
    sub.s32 %in_w_s32, %in_w_s32, %tmp_s32b;       // - pad_w
    cvt.s32.u32 %tmp_s32a, %rDw;
    cvt.s32.u32 %tmp_s32b, %kw;
    mul.lo.s32 %tmp_s32b, %tmp_s32a, %tmp_s32b;    // kw*dil_w
    add.s32 %in_w_s32, %in_w_s32, %tmp_s32b;
    // Bounds check W
    setp.lt.s32 %p_w_oob1, %in_w_s32, 0;
    cvt.s32.u32 %tmp_s32a, %rW;
    setp.ge.s32 %p_w_oob2, %in_w_s32, %tmp_s32a;
    or.pred %p_w_oob, %p_w_oob1, %p_w_oob2;
    @%p_w_oob bra INC_KW;
    // Compute x address
    cvt.u32.s32 %in_d_u32, %in_d_s32;
    cvt.u32.s32 %in_h_u32, %in_h_s32;
    cvt.u32.s32 %in_w_u32, %in_w_s32;
    cvt.u64.u32 %t64n,  %n;
    cvt.u64.u32 %t64_ci, %ci;
    cvt.u64.u32 %t64_id, %in_d_u32;
    cvt.u64.u32 %t64_ih, %in_h_u32;
    cvt.u64.u32 %t64_iw, %in_w_u32;
    mul.lo.u64 %x_idx_elems, %t64n,  %sX_n;
    mad.lo.u64 %x_idx_elems, %t64_ci, %sX_c, %x_idx_elems;
    mad.lo.u64 %x_idx_elems, %t64_id, %sX_d, %x_idx_elems;
    mad.lo.u64 %x_idx_elems, %t64_ih, %sX_h, %x_idx_elems;
    add.u64    %x_idx_elems, %x_idx_elems, %t64_iw;
    mul.lo.u64 %x_addr_bytes, %x_idx_elems, 4;
    add.u64    %x_addr_bytes, %x_addr_bytes, %r_x;
    // Compute w address: [oc, ci_rel, kd, kh, kw]
    cvt.u64.u32 %t64oc,    %oc;
    cvt.u64.u32 %t64cirel, %ci_rel;
    cvt.u64.u32 %t64kd,    %kd;
    cvt.u64.u32 %t64kh,    %kh;
    cvt.u64.u32 %t64kw,    %kw;
    mul.lo.u64 %w_idx_elems, %t64oc,    %sW_co;
    mad.lo.u64 %w_idx_elems, %t64cirel, %sW_ci, %w_idx_elems;
    mad.lo.u64 %w_idx_elems, %t64kd,    %sW_kd, %w_idx_elems;
    mad.lo.u64 %w_idx_elems, %t64kh,    %sW_kh, %w_idx_elems;
    add.u64    %w_idx_elems, %w_idx_elems, %t64kw;
    mul.lo.u64 %w_addr_bytes, %w_idx_elems, 4;
    add.u64    %w_addr_bytes, %w_addr_bytes, %r_w;
    // Load and accumulate
    ld.global.f32 %xval, [%x_addr_bytes];
    ld.global.f32 %wval, [%w_addr_bytes];
    mul.f32 %prod_f, %xval, %wval;
    add.f32 %acc, %acc, %prod_f;
INC_KW:
    add.u32 %kw, %kw, 1;
    bra KW_LOOP;
INC_KH:
    add.u32 %kh, %kh, 1;
    bra KH_LOOP;
INC_KD:
    add.u32 %kd, %kd, 1;
    bra KD_LOOP;
NEXT_CI:
    add.u32 %ci, %ci, 1;
    bra CI_LOOP;
WRITE_OUT:
    st.global.f32 [%y_byte_addr], %acc;
RET:
    ret;
}
"""
def _ptx_header_for_current_device():
    import torch
    try:
        cc = torch.cuda.get_device_capability()
        sm = cc[0] * 10 + cc[1]
    except Exception:
        sm = 80
    if sm >= 80:
        ptx_ver = "7.8"
        sm_target = "sm_80"
    elif sm >= 75:
        ptx_ver = "7.5"
        sm_target = "sm_75"
    else:
        ptx_ver = "7.0"
        sm_target = f"sm_{sm}"
    return f".version {ptx_ver}\n.target {sm_target}\n.address_size 64\n\n"
def _get_ptx_source():
    return _ptx_header_for_current_device() + PTX_BODY
_ptx_module = None
def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(_get_ptx_source())
        # Force PTX JIT assembly and entry-point lookup during compile validation.
        _ptx_module.function("conv3d_square_depth1")
    return _ptx_module
class ModelNew(nn.Module):
    """
    Performs a standard 3D convolution operation with an asymmetric input and a square kernel.

    Args:
        in_channels (int): Number of channels in the input tensor.
        out_channels (int): Number of channels produced by the convolution.
        kernel_size (int): Size of the square convolution kernel (kernel_size x kernel_size).
        stride (int, optional): Stride of the convolution. Defaults to 1.
        padding (int, optional): Padding applied to the input. Defaults to 0.
        dilation (int, optional): Spacing between kernel elements. Defaults to 1.
        groups (int, optional): Number of blocked connections from input channels to output channels. Defaults to 1.
        bias (bool, optional): If True, adds a learnable bias to the output. Defaults to False.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        if in_channels % groups != 0 or out_channels % groups != 0:
            raise ValueError("in_channels and out_channels must be divisible by groups")
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.groups = int(groups)
        # Weight shape: (out_channels, in_channels//groups, kD, kH, kW) with kW=1
        kD = self.kernel_size
        kH = self.kernel_size
        kW = 1
        self.weight = nn.Parameter(torch.empty(out_channels, in_channels // groups, kD, kH, kW))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.bias = None
        self.reset_parameters()

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = (self.in_channels // self.groups) * self.kernel_size * self.kernel_size * 1
            bound = 1.0 / math.sqrt(fan_in)
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Expect x in shape (N, C_in, D, H, W) as per torch.nn.Conv3d convention.
        # The provided test code uses x with shape (N, C, height, width, depth),
        # which maps to (N, C, D=height, H=width, W=depth) in Conv3d semantics.
        if not x.is_cuda:
            raise RuntimeError("Input must be a CUDA tensor")
        if x.dtype != torch.float32:
            raise RuntimeError("Only float32 tensors are supported")
        x = x.contiguous()
        device = x.device

        N, Cin, D, H, W = x.shape
        if Cin != self.in_channels:
            raise RuntimeError("Input channels do not match model definition")

        kD = self.kernel_size
        kH = self.kernel_size
        kW = 1

        Sd = self.stride
        Sh = self.stride
        Sw = self.stride

        Pd = self.padding
        Ph = self.padding
        Pw = self.padding

        Dd = self.dilation
        Dh = self.dilation
        Dw = self.dilation

        # Output dimensions
        def out_dim(Lin, pad, dil, k, stride):
            return (Lin + 2 * pad - dil * (k - 1) - 1) // stride + 1

        D_out = out_dim(D, Pd, Dd, kD, Sd)
        H_out = out_dim(H, Ph, Dh, kH, Sh)
        W_out = out_dim(W, Pw, Dw, kW, Sw)

        y = torch.empty((N, self.out_channels, D_out, H_out, W_out), device=device, dtype=x.dtype)

        module = _get_ptx_module()
        func_name = "conv3d_square_depth1"

        # Prepare bias pointer and has_bias flag
        if self.bias is not None:
            b = self.bias.contiguous()
            has_bias = 1
        else:
            b = torch.empty(1, device=device, dtype=x.dtype)
            has_bias = 0

        # Grid and block configuration
        block_x = 16
        block_y = 8
        block_z = 1
