    .reg .u32 rkD, rkH, rkW;
    .reg .u32 rSd, rSh, rSw;
    .reg .u32 rPd, rPh, rPw;
    .reg .u32 rDd, rDh, rDw;
    .reg .u32 rGroups, rHasBias;
    .reg .u32 rDo, rHo, rWo;

