    ld.param.u32 rCin,    [C_in];
    ld.param.u32 rCout,   [C_out];
    ld.param.u32 rD,      [D];
    ld.param.u32 rH,      [H];
    ld.param.u32 rW,      [W];
    ld.param.u32 rkD,     [kD];
    ld.param.u32 rkH,     [kH];
    ld.param.u32 rkW,     [kW];
    ld.param.u32 rSd,     [stride_d];
    ld.param.u32 rSh,     [stride_h];
    ld.param.u32 rSw,     [stride_w];
    ld.param.u32 rPd,     [pad_d];
    ld.param.u32 rPh,     [pad_h];
    ld.param.u32 rPw,     [pad_w];
    ld.param.u32 rDd,     [dil_d];
    ld.param.u32 rDh,     [dil_h];
    ld.param.u32 rDw,     [dil_w];
    ld.param.u32 rGroups, [groups];
    ld.param.u32 rHasBias,[has_bias];
    ld.param.u32 rDo,     [D_out];
    ld.param.u32 rHo,     [H_out];
    ld.param.u32 rWo,     [W_out];

    // Thread indices
    .reg .u32 tx, ty, bdx, bdy, bszx, bszy;
    mov.u32 tx, %tid.x;
    mov.u32 ty, %tid.y;
    mov.u32 bdx, %ctaid.x;
    mov.u32 bdy, %ctaid.y;
    mov.u32 bszx, %ntid.x;
    mov.u32 bszy, %ntid.y;

    .reg .u32 ow, oh;
    mad.lo.u32 ow, bdx, bszx, tx; // ow = blockIdx.x * blockDim.x + threadIdx.x
    mad.lo.u32 oh, bdy, bszy, ty; // oh = blockIdx.y * blockDim.y + threadIdx.y

    // Compute combined index from blockIdx.z
    .reg .u32 bidz;
    mov.u32 bidz, %ctaid.z;

    // Early bounds check on ow, oh
    .pred p_oob_xy;
    setp.ge.u32 p_oob_xy, ow, rWo;
    @p_oob_xy bra RET;
    setp.ge.u32 p_oob_xy, oh, rHo;
    @p_oob_xy bra RET;

    // Compute n, oc, od from bidz
    .reg .u32 co_do, n, rem1, oc, od;
    mul.lo.u32 co_do, rCout, rDo;           // C_out * D_out
    .reg .u32 qtmp, prod;
    div.u32 qtmp, bidz, co_do;              // n
    mul.lo.u32 prod, qtmp, co_do;           // n * (C_out*D_out)
    sub.u32 rem1, bidz, prod;               // remainder
