    cvt.u64.u32 tmp64a, rkW;
    mov.u64 sW_kh, tmp64a;                  // kH stride
    cvt.u64.u32 tmp64b, rkH;
    mul.lo.u64 sW_kd, tmp64a, tmp64b;       // kD stride
    cvt.u64.u32 tmp64c, rkD;
    mul.lo.u64 sW_ci, sW_kd, tmp64c;        // C_in_group stride
    cvt.u64.u32 tmp64a, gin;
    mul.lo.u64 sW_co, sW_ci, tmp64a;        // C_out stride

