        .reg .u64 b_off_bytes;
        .reg .u64 b_idx_elems;
        cvt.u64.u32 b_idx_elems, oc;
        mul.lo.u64 b_off_bytes, b_idx_elems, 4;
        add.u64 b_off_bytes, b_off_bytes, r_b;
