        Sh = self.stride
        Sw = self.stride

        Pd = self.padding
        Ph = self.padding
        Pw = self.padding

        Dd = self.dilation
        Dh = self.dilation
        Dw = self.dilation

        # Output dimensions
        def out_dim(Lin, pad, dil, k, stride):
            return (Lin + 2 * pad - dil * (k - 1) - 1) // stride + 1

        D_out = out_dim(D, Pd, Dd, kD, Sd)
        H_out = out_dim(H, Ph, Dh, kH, Sh)
