    mad.lo.u64 y_index_elems, t64oc, sY_c, y_index_elems;
    mad.lo.u64 y_index_elems, t64od, sY_d, y_index_elems;
    mad.lo.u64 y_index_elems, t64oh, sY_h, y_index_elems;
    add.u64    y_index_elems, y_index_elems, t64ow;
