    cvt.s32.u32 tmp_s32b, rPw;
    sub.s32 in_w_s32, in_w_s32, tmp_s32b;       // - pad_w
    cvt.s32.u32 tmp_s32a, rDw;
    cvt.s32.u32 tmp_s32b, kw;     // convert kw to s32
    mul.lo.s32 tmp_s32b, tmp_s32a, tmp_s32b;     // kw*dil_w
    add.s32 in_w_s32, in_w_s32, tmp_s32b;
    // Bounds check W
    .pred p_w_oob1, p_w_oob2, p_w_oob;
    setp.lt.s32 p_w_oob1, in_w_s32, 0;
    cvt.s32.u32 tmp_s32a, rW;
    setp.ge.s32 p_w_oob2, in_w_s32, tmp_s32a;
    or.pred p_w_oob, p_w_oob1, p_w_oob2;
