    cvt.u64.u32 t64_ci, ci;
    cvt.u64.u32 t64_id, in_d_u32;
    cvt.u64.u32 t64_ih, in_h_u32;
    cvt.u64.u32 t64_iw, in_w_u32;
    mul.lo.u64 x_idx_elems, t64_n,  sX_n;
    mad.lo.u64 x_idx_elems, t64_ci, sX_c, x_idx_elems;
    mad.lo.u64 x_idx_elems, t64_id, sX_d, x_idx_elems;
    mad.lo.u64 x_idx_elems, t64_ih, sX_h, x_idx_elems;
    add.u64    x_idx_elems, x_idx_elems, t64_iw;
    mul.lo.u64 x_addr_bytes, x_idx_elems, 4;
    add.u64    x_addr_bytes, x_addr_bytes, r_x;
    // Compute w address: [oc, ci_rel, kd, kh, kw]
    .reg .u64 w_idx_elems, w_addr_bytes, t64_oc, t64_cirel, t64_kd, t64_kh, t64_kw;
    cvt.u64.u32 t64_oc,    oc;
    cvt.u64.u32 t64_cirel, ci_rel;
    cvt.u64.u32 t64_kd,    kd;
    cvt.u64.u32 t64_kh,    kh;
    cvt.u64.u32 t64_kw,    kw;
    mul.lo.u64 w_idx_elems, t64_oc,    sW_co;
    mad.lo.u64 w_idx_elems, t64_cirel, sW_ci, w_idx_elems;
    mad.lo.u64 w_idx_elems, t64_kd,    sW_kd, w_idx_elems;
    mad.lo.u64 w_idx_elems, t64_kh,    sW_kh, w_idx_elems;
    add.u64    w_idx_elems, w_idx_elems, t64_kw;
    mul.lo.u64 w_addr_bytes, w_idx_elems, 4;
    add.u64    w_addr_bytes, w_addr_bytes, r_w;
