        sm = 80
    if sm >= 89:
        ptx_ver = "8.0"
        sm_target = f"sm_{sm}"
    elif sm >= 86:
        ptx_ver = "7.8"
        sm_target = f"sm_{sm}"
    elif sm >= 80:
        ptx_ver = "7.8"
        sm_target = "sm_80"
    elif sm >= 75:
        ptx_ver = "7.5"
        sm_target = "sm_75"
    else:
        ptx_ver = "7.0"
        sm_target = f"sm_{sm}"
    return f".version {ptx_ver}\n.target {sm_target}\n.address_size 64\n\n"
def _get_ptx_source():
