    .reg .u32 kh;
    mov.u32 kh, 0;
KH_LOOP:
    .pred p_kh_done;
    setp.ge.u32 p_kh_done, kh, rkH;
    @p_kh_done bra INC_KD;
    // Compute in_h = oh*stride_h - pad_h + kh*dil_h
    .reg .s32 in_h_s32, oh_s32;
    cvt.s32.u32 oh_s32, oh;
    cvt.s32.u32 tmp_s32a, rSh;
    mul.lo.s32 in_h_s32, oh_s32, tmp_s32a;      // oh*stride_h
    cvt.s32.u32 tmp_s32b, rPh;
    sub.s32 in_h_s32, in_h_s32, tmp_s32b;       // - pad_h
    cvt.s32.u32 tmp_s32a, rDh;
    cvt.s32.u32 tmp_s32b, kh;     // convert kh to s32
    mul.lo.s32 tmp_s32b, tmp_s32a, tmp_s32b;     // kh*dil_h
    add.s32 in_h_s32, in_h_s32, tmp_s32b;
