    .pred p_h_oob1, p_h_oob2, p_h_oob;
    setp.lt.s32 p_h_oob1, in_h_s32, 0;
    cvt.s32.u32 tmp_s32a, rH;
    setp.ge.s32 p_h_oob2, in_h_s32, tmp_s32a;
    or.pred p_h_oob, p_h_oob1, p_h_oob2;
    @p_h_oob bra INC_KH;
