INC_KW:
    add.u32 kw, kw, 1;
    bra KW_LOOP;
INC_KH:
    add.u32 kh, kh, 1;
    bra KH_LOOP;
INC_KD:
    add.u32 kd, kd, 1;
    bra KD_LOOP;
NEXT_CI:
