    .reg .u32 tx, ty, bdx, bdy, bszx, bszy;
    mov.u32 tx, %tid.x;
    mov.u32 ty, %tid.y;
    mov.u32 bdx, %ctaid.x;
    mov.u32 bdy, %ctaid.y;
    mov.u32 bszx, %ntid.x;
    mov.u32 bszy, %ntid.y;
