    .reg .u32 kd;
    mov.u32 kd, 0;
KD_LOOP:
    .pred p_kd_done;
    setp.ge.u32 p_kd_done, kd, rkD;
    @p_kd_done bra NEXT_CI;
    // Compute in_d = od*stride_d - pad_d + kd*dil_d
    .reg .s32 in_d_s32, tmp_s32a, tmp_s32b, od_s32;
