def _ptx_header_for_current_device():
    import torch
    try:
        cc = torch.cuda.get_device_capability()
        sm = cc[0] * 10 + cc[1]
    except Exception:
        sm = 80
    if sm >= 80:
        ptx_ver = "7.8"
        sm_target = "sm_80"
    elif sm >= 75:
        ptx_ver = "7.5"
        sm_target = "sm_75"
    else:
        ptx_ver = "7.0"
        sm_target = f"sm_{sm}"
    return f".version {ptx_ver}\n.target {sm_target}\n.address_size 64\n\n"
def _get_ptx_source():
    return _ptx_header_for_current_device() + PTX_BODY
_ptx_module = None
def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(_get_ptx_source())
        # Force PTX JIT assembly and entry-point lookup during compile validation.
        _ptx_module.function("conv3d_square_depth1")
    return _ptx_module
class ModelNew(nn.Module):
    """
    Performs a standard 3D convolution operation with an asymmetric input and a square kernel.

    Args:
        in_channels (int): Number of channels in the input tensor.
        out_channels (int): Number of channels produced by the convolution.
        kernel_size (int): Size of the square convolution kernel (kernel_size x kernel_size).
        stride (int, optional): Stride of the convolution. Defaults to 1.
        padding (int, optional): Padding applied to the input. Defaults to 0.
        dilation (int, optional): Spacing between kernel elements. Defaults to 1.
        groups (int, optional): Number of blocked connections from input channels to output channels. Defaults to 1.
        bias (bool, optional): If True, adds a learnable bias to the output. Defaults to False.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super().__init__()
        if in_channels % groups != 0 or out_channels % groups != 0:
            raise ValueError("in_channels and out_channels must be divisible by groups")
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.groups = int(groups)
        # Weight shape: (out_channels, in_channels//groups, kD, kH, kW) with kW=1
        kD = self.kernel_size
        kH = self.kernel_size
        kW = 1
        self.weight = nn.Parameter(torch.empty(out_channels, in_channels // groups, kD, kH, kW))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.bias = None
        self.reset_parameters()

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = (self.in_channels // self.groups) * self.kernel_size * self.kernel_size * 1
            bound = 1.0 / math.sqrt(fan_in)
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Expect x in shape (N, C_in, D, H, W) as per torch.nn.Conv3d convention.
        # The provided test code uses x with shape (N, C, height, width, depth),
        # which maps to (N, C, D=height, H=width, W=depth) in Conv3d semantics.
        if not x.is_cuda:
            raise RuntimeError("Input must be a CUDA tensor")
        if x.dtype != torch.float32:
            raise RuntimeError("Only float32 tensors are supported")
        x = x.contiguous()
        device = x.device

        N, Cin, D, H, W = x.shape
        if Cin != self.in_channels:
            raise RuntimeError("Input channels do not match model definition")

        kD = self.kernel_size
        kH = self.kernel_size
        kW = 1

        Sd = self.stride
        Sh = self.stride
        Sw = self.stride

        Pd = self.padding
        Ph = self.padding
        Pw = self.padding

        Dd = self.dilation
        Dh = self.dilation
        Dw = self.dilation

        # Output dimensions
        def out_dim(Lin, pad, dil, k, stride):
            return (Lin + 2 * pad - dil * (k - 1) - 1) // stride + 1

        D_out = out_dim(D, Pd, Dd, kD, Sd)
        H_out = out_dim(H, Ph, Dh, kH, Sh)
        W_out = out_dim(W, Pw, Dw, kW, Sw)

        y = torch.empty((N, self.out_channels, D_out, H_out, W_out), device=device, dtype=x.dtype)

        module = _get_ptx_module()
        func_name = "conv3d_square_depth1"

        # Prepare bias pointer and has_bias flag
        if self.bias is not None:
            b = self.bias.contiguous()
            has_bias = 1
        else:
            b = torch.empty(1, device=device, dtype=x.dtype)
            has_bias = 0

        # Grid and block configuration
        block_x = 16
        block_y = 8
        block_z = 1
        grid_x = (W_out + block_x - 1) // block_x
        grid_y = (H_out + block_y - 1) // block_y
        grid_z = N * self.out_channels * D_out

        module.launch(
            func_name,
            grid=(grid_x, grid_y, grid_z),
            block=(block_x, block_y, block_z),
            arguments=[
                x, self.weight, b, y,
                i32(N), i32(Cin), i32(self.out_channels),
                i32(D), i32(H), i32(W),
                i32(kD), i32(kH), i32(kW),
                i32(Sd), i32(Sh), i32(Sw),
                i32(Pd), i32(Ph), i32(Pw),
                i32(Dd), i32(Dh), i32(Dw),
                i32(self.groups), i32(has_bias),
                i32(D_out), i32(H_out), i32(W_out),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(device),
        )
        return y

