    // x indexing temps
    .reg .u64 %x_idx_elems, %x_addr_bytes, %t64_ci, %t64_id, %t64_ih, %t64_iw;
    // w indexing temps
    .reg .u64 %w_idx_elems, %w_addr_bytes, %t64cirel, %t64kd, %t64kh, %t64kw;
    // Accumulators and values
    .reg .f32 %acc, %bias_val, %xval, %wval, %prod_f;
