    div.u32 %gout, %rCout, %rGroups;           // out channels per group
    div.u32 %gin,  %rCin,  %rGroups;           // in channels per group
    div.u32 %grp,  %oc,    %gout;              // group id
    mul.lo.u32 %ci_start, %grp, %gin;          // start in-channel
    add.u32 %ci_end, %ci_start, %gin;          // end in-channel
    // Precompute strides for x (N,C,D,H,W)
    mov.u64 %sX_w, 1;
