    cvt.s32.u32 %tmp_s32a, %rDh;
    cvt.s32.u32 %tmp_s32b, %kh;
    mul.lo.s32 %tmp_s32b, %tmp_s32a, %tmp_s32b;    // kh*dil_h
    add.s32 %in_h_s32, %in_h_s32, %tmp_s32b;
