    setp.lt.s32 %p_h_oob1, %in_h_s32, 0;
    cvt.s32.u32 %tmp_s32a, %rH;
    setp.ge.s32 %p_h_oob2, %in_h_s32, %tmp_s32a;
    or.pred %p_h_oob, %p_h_oob1, %p_h_oob2;
    @%p_h_oob bra INC_KH;
    // kw loop
    mov.u32 %kw, 0;
KW_LOOP:
    setp.ge.u32 %p_kw_done, %kw, %rkW;
    @%p_kw_done bra INC_KH;
    // Compute in_w = ow*stride_w - pad_w + kw*dil_w
    cvt.s32.u32 %ow_s32, %ow;
    cvt.s32.u32 %tmp_s32a, %rSw;
    mul.lo.s32 %in_w_s32, %ow_s32, %tmp_s32a;      // ow*stride_w
    cvt.s32.u32 %tmp_s32b, %rPw;
    sub.s32 %in_w_s32, %in_w_s32, %tmp_s32b;       // - pad_w
    cvt.s32.u32 %tmp_s32a, %rDw;
    cvt.s32.u32 %tmp_s32b, %kw;
    mul.lo.s32 %tmp_s32b, %tmp_s32a, %tmp_s32b;    // kw*dil_w
    add.s32 %in_w_s32, %in_w_s32, %tmp_s32b;
    // Bounds check W
    setp.lt.s32 %p_w_oob1, %in_w_s32, 0;
    cvt.s32.u32 %tmp_s32a, %rW;
    setp.ge.s32 %p_w_oob2, %in_w_s32, %tmp_s32a;
    or.pred %p_w_oob, %p_w_oob1, %p_w_oob2;
    @%p_w_oob bra INC_KW;
    // Compute x address
    cvt.u32.s32 %in_d_u32, %in_d_s32;
    cvt.u32.s32 %in_h_u32, %in_h_s32;
    cvt.u32.s32 %in_w_u32, %in_w_s32;
    cvt.u64.u32 %t64n,  %n;
    cvt.u64.u32 %t64_ci, %ci;
    cvt.u64.u32 %t64_id, %in_d_u32;
    cvt.u64.u32 %t64_ih, %in_h_u32;
    cvt.u64.u32 %t64_iw, %in_w_u32;
    mul.lo.u64 %x_idx_elems, %t64n,  %sX_n;
    mad.lo.u64 %x_idx_elems, %t64_ci, %sX_c, %x_idx_elems;
    mad.lo.u64 %x_idx_elems, %t64_id, %sX_d, %x_idx_elems;
    mad.lo.u64 %x_idx_elems, %t64_ih, %sX_h, %x_idx_elems;
    add.u64    %x_idx_elems, %x_idx_elems, %t64_iw;
    mul.lo.u64 %x_addr_bytes, %x_idx_elems, 4;
    add.u64    %x_addr_bytes, %x_addr_bytes, %r_x;
    // Compute w address: [oc, ci_rel, kd, kh, kw]
    cvt.u64.u32 %t64oc,    %oc;
    cvt.u64.u32 %t64cirel, %ci_rel;
    cvt.u64.u32 %t64kd,    %kd;
    cvt.u64.u32 %t64kh,    %kh;
    cvt.u64.u32 %t64kw,    %kw;
    mul.lo.u64 %w_idx_elems, %t64oc,    %sW_co;
    mad.lo.u64 %w_idx_elems, %t64cirel, %sW_ci, %w_idx_elems;
    mad.lo.u64 %w_idx_elems, %t64kd,    %sW_kd, %w_idx_elems;
    mad.lo.u64 %w_idx_elems, %t64kh,    %sW_kh, %w_idx_elems;
    add.u64    %w_idx_elems, %w_idx_elems, %t64kw;
    mul.lo.u64 %w_addr_bytes, %w_idx_elems, 4;
    add.u64    %w_addr_bytes, %w_addr_bytes, %r_w;
    // Load and accumulate
    ld.global.f32 %xval, [%x_addr_bytes];
    ld.global.f32 %wval, [%w_addr_bytes];
    mul.f32 %prod_f, %xval, %wval;
    add.f32 %acc, %acc, %prod_f;
INC_KW:
    add.u32 %kw, %kw, 1;
    bra KW_LOOP;
INC_KH:
    add.u32 %kh, %kh, 1;
    bra KH_LOOP;
INC_KD:
    add.u32 %kd, %kd, 1;
    bra KD_LOOP;
NEXT_CI:
    add.u32 %ci, %ci, 1;
    bra CI_LOOP;
WRITE_OUT:
    st.global.f32 [%y_byte_addr], %acc;
